// Kho dữ liệu biên soạn sẵn để trình diễn quy trình xử lý trước khi doanh nghiệp truy cập.
// Văn bản và điều/khoản là nguồn thật; diễn giải/checklist được biên soạn thủ công,
// chưa chạy AI trực tiếp và chưa thay thế thẩm định pháp lý.

const finding = (clause, importantPoint, affectedGroups, conditionLabel, templateIds) =>
  ({ clause, importantPoint, affectedGroups, conditionLabel, templateIds });
const buildChecks = (detail, evidence) => {
  const actions = String(detail).split(/[.;]\s+/).map(item => item.trim()).filter(Boolean).slice(0, 3).map(item => item.endsWith('.') ? item : `${item}.`);
  if (actions.length < 2) actions.push(`Đối chiếu nội dung trên với hồ sơ thực tế và tài liệu: ${evidence}`);
  actions.push('Ghi kết quả đối chiếu, điểm thiếu, người phụ trách và hạn xử lý nếu có.');
  return actions;
};
const step = (title, detail, evidence, refs, when = '', checks = []) => ({
  title, detail, evidence, when, checks: checks.length ? checks : buildChecks(detail, evidence),
  refs: refs.map(([sourceId, clause]) => ({ sourceId, clause })),
});

