export function templateMatch(profile, template) {
  const { field, includes, anyOf } = template.match;
  const value = profile?.[field];
  if (Array.isArray(value)) return value.includes(includes) ? 'match' : 'unknown';
  if (anyOf) return anyOf.includes(value) ? 'match' : value === '0' ? 'no-match' : 'unknown';
  return 'unknown';
}

export const checklistTemplateById = id => checklistTemplates.find(template => template.id === id);
